fn blur_thick(pos: vec2<f32>, dir: vec2<f32>) -> vec4<f32> {
    let dims = vec2<f32>(textureDimensions(thick_in));
    let uv = pos / dims;
    let step = dir / dims;
    var acc = textureSampleLevel(thick_in, blur_sampler, uv, 0.0) * 0.227027;
    let o1 = step * 2.55;
    let o2 = step * 5.85;
    acc += (textureSampleLevel(thick_in, blur_sampler, uv + o1, 0.0) + textureSampleLevel(thick_in, blur_sampler, uv - o1, 0.0)) * 0.316216;
    acc += (textureSampleLevel(thick_in, blur_sampler, uv + o2, 0.0) + textureSampleLevel(thick_in, blur_sampler, uv - o2, 0.0)) * 0.07027;
    return acc;
}

